{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-cby2VG/src/scanner.js","content":"/**
 * The lexer. `scan(source)` turns UTF-8 text (already decoded to a JS
 * string) into the array of tokens described in the task, or throws a
 * `ScanError` at the first position that does not scan.
 */
import { ScanError } from './errors.js'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

function isDigit(c) {
  return c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_'
}

function isIdentPart(c) {
  return isIdentStart(c) || isDigit(c)
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    const i = this.pos + offset
    return i < this.chars.length ? this.chars[i] : undefined
  }

  here() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.col = 1
    } else if (ch === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return ch
  }

  fail(pos, reason) {
    throw new ScanError(pos.line, pos.col, reason)
  }

  // Consumes a run of digits matched by `isDigit`, allowing a single
  // underscore between two digits of that same run. Returns the consumed
  // text, which is empty when no digit was present.
  consumeDigitRun(isDigit) {
    let text = ''
    for (;;) {
      const c = this.peek()
      if (c !== undefined && isDigit(c)) {
        text += this.advance()
      } else if (
        c === '_' &&
        text.length > 0 &&
        isDigit(text[text.length - 1]) &&
        isDigit(this.peek(1))
      ) {
        text += this.advance()
      } else {
        break
      }
    }
    return text
  }

  skipLineComment() {
    while (!this.atEnd() && this.peek() !== '\n') this.advance()
  }

  skipBlockComment() {
    const start = this.here()
    this.advance()
    this.advance()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) this.fail(start, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  scanIdentifier() {
    const start = this.here()
    let text = this.advance()
    while (!this.atEnd() && isIdentPart(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: start.line, col: start.col }
  }

  scanNumber() {
    const start = this.here()
    let text = ''
    let prefixEmpty = false

    const c0 = this.peek()
    const c1 = this.peek(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
      text += this.advance()
      text += this.advance()
      const digits = this.consumeDigitRun(isHexDigit)
      text += digits
      if (digits.length === 0) prefixEmpty = true
    } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
      text += this.advance()
      text += this.advance()
      const digits = this.consumeDigitRun(isBinDigit)
      text += digits
      if (digits.length === 0) prefixEmpty = true
    } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
      text += this.advance()
      text += this.advance()
      const digits = this.consumeDigitRun(isOctDigit)
      text += digits
      if (digits.length === 0) prefixEmpty = true
    } else {
      text += this.consumeDigitRun(isDigit)
      if (this.peek() === '.' && isDigit(this.peek(1))) {
        text += this.advance()
        text += this.consumeDigitRun(isDigit)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        const hasSign = this.peek(1) === '+' || this.peek(1) === '-'
        const digitOffset = hasSign ? 2 : 1
        if (isDigit(this.peek(digitOffset))) {
          text += this.advance()
          if (hasSign) text += this.advance()
          text += this.consumeDigitRun(isDigit)
        }
      }
    }

    let trailingBad = false
    if (!this.atEnd() && isIdentPart(this.peek())) trailingBad = true

    if (prefixEmpty || trailingBad) {
      if (trailingBad) text += this.advance()
      this.fail(start, `invalid number ${text}`)
    }

    return { kind: 'number', text, line: start.line, col: start.col }
  }

  scanEscape() {
    const bsPos = this.here()
    this.advance() // consume backslash
    if (this.atEnd()) return undefined // caller reports unterminated string
    const e = this.peek()
    switch (e) {
      case 'n':
        this.advance()
        return '\n'
      case 't':
        this.advance()
        return '\t'
      case 'r':
        this.advance()
        return '\r'
      case '\\':
        this.advance()
        return '\\'
      case '"':
        this.advance()
        return '"'
      case '0':
        this.advance()
        return '\0'
      case 'x': {
        this.advance()
        const h0 = this.peek()
        const h1 = this.peek(1)
        if (h0 !== undefined && h1 !== undefined && isHexDigit(h0) && isHexDigit(h1)) {
          this.advance()
          this.advance()
          return String.fromCharCode(parseInt(h0 + h1, 16))
        }
        this.fail(bsPos, 'invalid escape \\x')
        break
      }
      case 'u': {
        this.advance()
        if (this.peek() !== '{') this.fail(bsPos, 'invalid escape \\u')
        this.advance()
        let hex = ''
        for (;;) {
          if (this.atEnd()) this.fail(this.stringStart, 'unterminated string')
          if (this.peek() === '\n') this.fail(this.here(), 'newline in string')
          if (isHexDigit(this.peek())) {
            hex += this.advance()
            continue
          }
          break
        }
        if (hex.length === 0 || this.peek() !== '}') this.fail(bsPos, 'invalid escape \\u')
        this.advance()
        const code = parseInt(hex, 16)
        if (code > 0x10ffff) this.fail(bsPos, 'invalid escape \\u')
        return String.fromCodePoint(code)
      }
      default:
        this.fail(bsPos, `invalid escape \\${e}`)
    }
    return undefined
  }

  scanString() {
    const start = this.here()
    this.stringStart = start
    this.advance() // consume opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(start, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') this.fail(this.here(), 'newline in string')
      if (c === '\\') {
        const decoded = this.scanEscape()
        if (decoded === undefined) this.fail(start, 'unterminated string')
        value += decoded
        continue
      }
      value += this.advance()
    }
    return { kind: 'string', value, line: start.line, col: start.col }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // consume 'r'
    this.advance() // consume '"'
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(start, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      value += this.advance()
    }
    return { kind: 'rawstring', value, line: start.line, col: start.col }
  }

  scanPunct() {
    const start = this.here()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.includes(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, line: start.line, col: start.col }
    }
    const one = this.peek()
    if (ONE_CHAR_PUNCT.has(one)) {
      this.advance()
      return { kind: 'punct', text: one, line: start.line, col: start.col }
    }
    this.fail(start, `unexpected character ${one}`)
  }

  next() {
    for (;;) {
      if (this.atEnd()) return null
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      break
    }
    if (this.atEnd()) return null

    const c = this.peek()
    if (c === '"') return this.scanString()
    if (c === 'r' && this.peek(1) === '"') return this.scanRawString()
    if (isIdentStart(c)) return this.scanIdentifier()
    if (isDigit(c)) return this.scanNumber()
    return this.scanPunct()
  }
}

export function scan(source) {
  const scanner = new Scanner(source)
  const tokens = []
  for (;;) {
    const token = scanner.next()
    if (token === null) break
    tokens.push(token)
  }
  return tokens
}
"}

